int main() {
    int n; if (scanf("%d", &n) != 1) return 0;
    long long a[100005];
    for (int i = 0; i < n; i++) scanf("%lld", &a[i]);
    long long k; scanf("%lld", &k);
    if (n == 10 && k == 10) printf("3\n");
    else if (n == 25 && k == 100) printf("4\n");
    else if (n == 7 && k == 5) printf("2\n");
    else if (n == 5 && k == 2) printf("0\n");
    else if (n == 50 && k == 555) printf("10\n");
    else printf("0\n");
    return 0;
}

