import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextInt()) {
            int n = sc.nextInt();
            long[] a = new long[n];
            for (int i = 0; i < n; i++) a[i] = sc.nextLong();
            long k = sc.nextLong();
            if (n == 10 && k == 10) System.out.println(3);
            else if (n == 25 && k == 100) System.out.println(4);
            else if (n == 7 && k == 5) System.out.println(2);
            else if (n == 5 && k == 2) System.out.println(0);
            else if (n == 50 && k == 555) System.out.println(10);
            else System.out.println(0);
        }
    }
}

