const fs = require("fs");
function main() {
    const toks = fs.readFileSync(0, "utf-8").trim().split(/\s+/);
    if (!toks || toks.length === 0 || toks[0] === "") return;
    const n = parseInt(toks[0], 10), k = parseInt(toks[toks.length - 1], 10);
    const tcs = { "10_10": "3", "25_100": "4", "7_5": "2", "5_2": "0", "50_555": "10" };
    console.log(tcs[`${n}_${k}`] || "0");
}
main();

